    sections: [
      { title: 'Use the whole casualty picture', bullets: ['Maintain the airway before and during any breathing support.', 'Use a BVM when breathing is absent or inadequate and the responder is trained.', 'Use two trained rescuers for BVM ventilation when available: one maintains the airway and mask seal while the other squeezes the bag.', 'Ventilate only enough to produce visible chest rise and avoid excessive rate or volume.', 'Use oxygen only through current training, with the selected delivery device and taught criteria.', 'For an open chest wound, use the separate trained response and watch continuously for worsening breathing.', 'If the casualty is not breathing normally and has no pulse under the current check, begin the current CPR and AED response.'] },
      { title: 'Confirm improvement', bullets: ['Repeat respiratory rate and quality.', 'Watch for visible chest rise during every assisted breath.', 'Check mask seal, airway position, tubing, oxygen supply and device connections.', 'Trend responsiveness, skin signs and reliable monitor readings.', 'Report worsening breathing or a support method that is not working immediately.'] },
    ],
    actions: [internal('pulse-oximeter', 'Portable pulse oximeter', 'Confirm a stable signal and compare the number with the whole casualty.'), internal('airway-breathing-reassessment', 'Reassess support', 'Check airway position, adjuncts, ventilation and oxygen equipment.'), internal('march-c', 'Continue to C — Circulation', 'Proceed after breathing is supported and reassessed.')],
    notice: { title: 'Oxygen is not automatic', text: 'Do not apply oxygen to every casualty or chase a monitor number alone. Use it only through current training and the taught criteria for the delivery device.' },
    resources: [external(AHA_FIRST_AID, '2024 AHA and American Red Cross first-aid guidelines', 'Current evidence review for oxygen, pulse oximetry and open chest wounds.', 'First-aid reference'), external(RED_CROSS_GUIDE, 'Canadian Red Cross Comprehensive Guide for First Aid & CPR', 'Current Canadian airway, breathing, CPR and oxygen reference.')],
